public class GymMembership { static class GymMember{String id;int fee,sessions;GymMember(String id,int fee){if(id==null||id.trim().length()<4)throw new IllegalArgumentException();this.id=id;this.fee=fee;}GymMember(int fee){this("MEM1",fee);}void attendSession(){sessions++;}int getSessionsAttended(){return sessions;}void displayInfo(){System.out.println("Standard Member | Sessions: "+sessions);}} static class PremiumMember extends GymMember{String trainer;PremiumMember(String i,int f,String t){super(i,f);trainer=t;}@Override void displayInfo(){System.out.println("Premium Member | Trainer: "+trainer+" | Sessions: "+sessions);}} static class EliteMember extends PremiumMember{String locker;EliteMember(String i,int f,String t,String l){super(i,f,t);locker=l;}@Override void displayInfo(){System.out.println("Elite Member | Trainer: "+trainer+" | Locker: "+locker+" | Sessions: "+sessions);}} static class GroupClassMember extends GymMember{String cls;GroupClassMember(String i,int f,String c){super(i,f);cls=c;}GroupClassMember(int f,String c){super(f);cls=c;}@Override void displayInfo(){System.out.println("Group Class Member | Class: "+cls+" | Sessions: "+sessions);}} static String signUpBatch(String[]a,int f){int s=0,r=0;for(String x:a)try{new GymMember(x,f);s++;}catch(Exception e){r++;}return "Signed Up: "+s+" | Rejected: "+r;} public static void main(String[]x){System.out.println(signUpBatch(new String[]{"MEM1","GM1","MEM2"," ","MEM3"},1000));}}
